// Задачи подаются через метод Submit и выполняются в фоновых горутинах.
// Количество одновременно выполняемых задач не превышает maxWorkers.
type Pool struct {
	taskCh     chan Task   // Канал для приёма задач от отправителей
	ctx        context.Context // Контекст для управления жизненным циклом пула
	cancel     context.CancelFunc // Функция отмены контекста
	wg         sync.WaitGroup      // WaitGroup для ожидания завершения всех воркеров
	maxWorkers int               // Максимальное количество параллельных воркеров
}

// New создаёт новый пул воркеров с указанным максимальным количеством параллельных задач.
