// Если maxWorkers <= 0, будет использовано значение по умолчанию (1).
// Пул начинает работу сразу после создания; для остановки используйте метод Stop.
func New(maxWorkers int) *Pool {
	if maxWorkers <= 0 {
		maxWorkers = 1
	}

	// Создаём контекст с возможностью отмены.
	// ctx используется для передачи сигнала остановки всем воркерам.
	ctx, cancel := context.WithCancel(context.Background())

