/**
 * Клиент WebSocket с автоматическим переподключением и очередью исходящих сообщений.
 *
 * Основные возможности:
 *  - Автоматическое переподключение при обрыве соединения (с экспоненциальной задержкой).
 *  - Очередь исходящих сообщений: если соединение разорвано, сообщения не теряются,
 *    а сохраняются в памяти и отправляются после восстановления связи.
 *  - Поддержка отправки строк и JSON-объектов.
 *  - Событийная модель для обработки входящих данных и состояния соединения.
 */

// ─────────────────────────────────────────────
// Типы и интерфейсы
// ─────────────────────────────────────────────

/**
 * Конфигурация клиента WebSocket.
 */
export interface WebSocketClientOptions {
  /** URL сервера WebSocket (например, "wss://example.com/ws"). */
  url: string;

  /** Максимальное количество попыток переподключения. По умолчанию: 10. */
  maxReconnectAttempts?: number;

  /** Базовая задержка перед первой попыткой переподключения (мс). По умолчанию: 1000. */
  baseReconnectDelay?: number;

  /** Множитель для экспоненциального увеличения задержки. По умолчанию: 2. */
  reconnectBackoffMultiplier?: number;

  /** Максимальная задержка между попытками переподключения (мс). По умолчанию: 30000. */
  maxReconnectDelay?: number;

  /**
   * Функция сериализации сообщения перед отправкой.
   * Если не указана, используется JSON.stringify для объектов и String() для примитивов.
   */
  serializer?: (data: unknown) => string;

  /**
   * Функция десериализации входящего сообщения.
   * Если не указана, пытается распарсить как JSON, иначе возвращает строку.
   */
  deserializer?: (raw: string) => unknown;

  /**
   * Таймаут ожидания ответа на ping (если используется keep-alive).
   * Не реализован в базовой версии, но может быть расширен.
   */
  pingInterval?: number;
}

/**
 * Возможные события клиента.
 */
export type WebSocketEvent =
