//! Парсер аргументов командной строки для утилиты сжатия файлов.
//!
//! Поддерживает следующие опции:
//! - `-o, --output <FILE>` — файл вывода (архив)
//! - `-d, --decompress` — режим распаковки
//! - `-f, --force` — перезаписать существующий файл без подтверждения
//! - `-v, --verbose` — подробный вывод в консоль
//! - `-h, --help` — показать справку
//! - `--version` — показать версию программы
//! - Позиционные аргументы — список входных файлов/каталогов

use std::env;
use std::fmt;
use std::path::PathBuf;

/// Ошибка парсинга аргументов командной строки.
#[derive(Debug)]
pub enum ParseError {
    /// Неизвестная опция.
    UnknownOption(String),
    /// Опция требует значение, но оно не было передано.
    MissingValueForOption(String),
    /// Дублирующаяся опция.
    DuplicateOption(String),
    /// Невалидное значение для опции.
    InvalidValue { option: String, value: String, reason: String },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::UnknownOption(opt) => write!(f, "неизвестная опция: {}", opt),
            ParseError::MissingValueForOption(opt) => {
                write!(f, "опция {} требует значение", opt)
            }
            ParseError::DuplicateOption(opt) => {
                write!(f, "опция {} задана более одного раза", opt)
            }
            ParseError::InvalidValue { option, value, reason } => {
                write!(f, "невалидное значение '{}' для опции {}: {}", value, option, reason)
            }
        }
    }
}

/// Результат успешного парсинга аргументов командной строки.
