/// <summary>
/// Возвращает последовательность уникальных элементов исходной коллекции,
/// где уникальность определяется по значению ключа, полученному из функции key.
/// </summary>
/// <typeparam name="T">Тип элементов исходной коллекции.</typeparam>
/// <typeparam name="K">Тип ключа, по которому проверяется уникальность.</typeparam>
/// <param name="src">Исходная коллекция элементов.</param>
/// <param name="key">Функция, вычисляющая ключ для каждого элемента.</param>
/// <returns>Последовательность элементов, у которых ключи не повторяются (первое вхождение сохраняется).</returns>
public static IEnumerable<T> Distinct<T, K>(this IEnumerable<T> src, Func<T, K> key)
{
    // Множество для хранения уже встреченных ключей.
    // HashSet обеспечивает быструю проверку наличия элемента (O(1)).
    var seen = new HashSet<K>();

    // Перебираем каждый элемент исходной коллекции
    foreach (var x in src)
    {
        // Вычисляем ключ текущего элемента и пытаемся добавить его в множество seen.
        // Метод Add возвращает true, если ключ был добавлен впервые (т.е. ранее не встречался),
        // и false, если такой ключ уже есть в множестве.
        if (seen.Add(key(x)))
        {
            // Если ключ новый — отдаём текущий элемент наружу через yield return.
            // Это позволяет реализовать ленивую оценку (lazy evaluation):
            // элементы генерируются только при обращении к ним потребителем.
            yield return x;
        }
    }
}
