/**
 * Создаёт функцию с дебаунсингом (задержкой выполнения).
 * 
 * @param fn - Функция, которую нужно обернуть в дебаунс.
 *             Ограничение: функция должна принимать любые аргументы и возвращать void.
 * @param ms - Время задержки в миллисекундах перед выполнением функции.
 * @returns Обёрнутая функция, которая будет вызывать `fn` только после того,
 *          как перестанут приходить вызовы в течение указанного времени.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Изначально не задана (undefined), так как таймер ещё не создан.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная `fn`.
  return (...args: Parameters<T>) => {
    // Если таймер уже существует (предыдущий вызов ещё не отработал),
    // очищаем его, чтобы отменить предыдущее запланированное выполнение.
    if (timer) clearTimeout(timer);

    // Устанавливаем новый таймер на время `ms`.
    // По истечении этого времени будет вызвана исходная функция `fn`
    // с последними переданными аргументами (`args`).
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

