/**
 * Универсальная функция для повторного выполнения блока кода при возникновении IOException.
 *
 * @param times Количество попыток выполнения блока.
 * @param block Лямбда-функция, содержащая код, который нужно выполнить.
 * @return Результат выполнения блока (тип T).
 * @throws IOException Если все попытки завершились исключением IOException.
 * @throws IllegalStateException Если количество попытк равно нулю или меньше.
 */
fun <T> retry(times: Int, block: () -> T): T {
    // Переменная для хранения последнего возникшего исключения (IOException)
    var last: Throwable? = null

    // Цикл, выполняющий блок `times` раз
    repeat(times) {
        try {
            // Пытаемся выполнить переданный блок кода
            // Если выполнение успешно — сразу возвращаем результат
            return block()
        } catch (e: IOException) {
            // Если произошло исключение IOException, сохраняем его в переменную `last`
            // и продолжаем цикл (переходим к следующей попытке)
            last = e
        }
    }

    // Если все попытки исчерпаны и ни одна не завершилась успехом:
    // - если `last` содержит сохранённое исключение — бросаем его
    // - иначе (например, если times <= 0) бросаем IllegalStateException с пояснением
    throw last ?: IllegalStateException("times must be > 0")
}
```

