// Get возвращает значение из кэша по указанному ключу.
//
// Функция выполняет чтение из кэша с использованием блокировки чтения (RLock),
// что позволяет нескольким горутинам одновременно читать данные без взаимной блокировки,
// но исключает одновременное изменение состояния кэша во время чтения.
//
// Параметры:
//   - key: строковый ключ, по которому ищется значение в кэше.
//     Ключ должен быть непустым; пустая строка будет обработана как обычный ключ,
//     если он был ранее сохранён.
//
// Возвращаемые значения:
//   - string: значение, связанное с ключом, если оно найдено и не истекло.
//     Если значение не найдено или срок его действия истёк, возвращается пустая строка "".
//   - bool: флаг, указывающий на успешность получения значения.
//     true — значение найдено и актуально; false — значение отсутствует или устарело.
//
// Поведение при граничных случаях:
//   - Если ключ не существует в кэше, функция возвращает ("", false).
//   - Если ключ существует, но время жизни записи (TTL) истекло (time.Now().After(e.expires)),
//     запись считается устаревшей, и функция возвращает ("", false).
//     Обратите внимание: устаревшая запись не удаляется из памяти немедленно —
//     её очистка может происходить асинхронно или при следующем обращении,
//     в зависимости от реализации внутренней структуры кэша.
//   - Пустой ключ "" обрабатывается как обычный ключ: если он был сохранён ранее,
//     значение будет возвращено; иначе — ("", false).
//
// Исключения:
//   - Функция не паникует при нормальном использовании.
//   - При передаче nil-ссылки на c (*Cache) произойдёт паника (nil pointer dereference),
//     так как метод вызывается на нулевой ссылке.
//
// Примечание:
//   - Функция является потокобезопасной благодаря использованию RWMutex.
//   - Не рекомендуется вызывать Get в цикле с высокой частотой без учёта накладных расходов
//     на блокировку, хотя RLock значительно дешевле полной блокировки.
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok || time.Now().After(e.expires) {
		return "", false
	}
	return e.value, true
}
