    // Фиксируем дату рождения
    val birthDate = LocalDate.of(2006, 9, 24)

    // Передаём фиксированную "текущую" дату, когда пользователю точно есть 18+
    // Например, 1 января 2025 года — тогда ему будет 18 лет
    val fixedCurrentDate = LocalDate.of(2025, 1, 1)

    val u = User(birthDate = birthDate)

    // Проверяем, что при фиксированной дате пользователь считается взрослым
    assertTrue(u.isAdult(fixedCurrentDate), "Пользователь должен быть взрослым на $fixedCurrentDate")
}
```

